// 13_wav ports the M5Stack CoreS3 "Audio Files" Arduino tutorial: play
// /sample-12s.wav from the microSD card once, logging to the screen (black
// text on white) and the serial port.
//
// ref: https://docs.m5stack.com/ja/arduino/m5cores3/wav
//
// The tutorial loads the file into memory, or plays it in 16 KB segments when
// it does not fit. Here the file is streamed into the I2S DMA ring as it is
// read, which needs only a 4 KB buffer. The test file is generated by
// tools/sdput/genwav.py and copied with tools/sdput.
package main

import (
	"time"

	"esp32-s3-lite/cores3"
	"esp32-s3-lite/internal/gfx"
	"esp32-s3-lite/internal/wav"

	"tinygo.org/x/tinyfont/freemono"
)

const fileName = "/sample-12s.wav"

// volume scales the samples (256 = as recorded).
// TODO(verify): M5Unified plays at master volume 64 by default; its scaling is
// not reproduced exactly.
const volume = 128

var (
	con     gfx.Console
	line    [64]byte
	readBuf [4096]byte
	pcm     [2048]int16
)

func log(s string) {
	println(s)
	con.Print(s)
	con.Print("\n")
}

func main() {
	time.Sleep(2 * time.Second) // give the serial monitor time to attach
	println("=== 13_wav ===")

	if err := cores3.Init(); err != nil {
		println("Init failed:", err.Error())
	}
	d, err := cores3.InitDisplay()
	if err != nil {
		println("InitDisplay failed:", err.Error())
	}
	cores3.Verbose = false
	d.FillRectangle565(0, 0, 320, 240, gfx.White)
	con = gfx.Console{D: d, Font: &freemono.Bold9pt7b, Fore: gfx.Black, Back: gfx.White}

	if err := cores3.InitSD(); err != nil {
		log("Card failed, or not present")
		halt()
	}
	s := append(line[:0], "SD Card Size: "...)
	s = gfx.Itoa(s, int(cores3.SD.Size()/(1024*1024)))
	log(gfx.String(append(s, "MB"...)))

	log("Starting audio playback...")
	playWAV(fileName)
	halt()
}

func playWAV(path string) {
	fi, err := cores3.FS.Stat(path)
	if err != nil {
		log("File does not exist!")
		return
	}
	f, err := cores3.FS.Open(path)
	if err != nil {
		log("Failed to open file!")
		return
	}
	defer f.Close()
	s := append(line[:0], "File size: "...)
	s = gfx.Itoa(s, int(fi.Size()))
	log(gfx.String(append(s, " Byte"...)))

	fm, err := wav.ReadHeader(f)
	if err != nil {
		log(err.Error())
		return
	}
	s = append(line[:0], "WAV: "...)
	s = gfx.Itoa(s, int(fm.SampleRate))
	s = append(s, "Hz, "...)
	s = gfx.Itoa(s, int(fm.Channels))
	s = append(s, "ch, "...)
	s = gfx.Itoa(s, int(fm.BitsPerSample))
	log(gfx.String(append(s, "bit"...)))

	// The speaker always runs at 48 kHz mono (as M5Unified): stereo data is
	// mixed down and every rate is resampled. The CoreS3 amplifier plays the
	// left slot only and stays silent at 44.1 kHz (docs/notes.md).
	if err := cores3.StartSpeaker(cores3.SpeakerSampleRate); err != nil {
		log("Speaker start failed")
		return
	}
	log("Starting streamed playback...")
	start := time.Now()
	remain := int(fm.DataSize)
	read := 0
	nextReport := 0
	for remain > 0 {
		n := len(readBuf)
		if n > remain {
			n = remain
		}
		got, err := f.Read(readBuf[:n])
		if got <= 0 || (err != nil && got == 0) {
			break
		}
		remain -= got
		read += got
		k := 0
		bps := int(fm.BitsPerSample / 8)
		frame := bps * int(fm.Channels)
		for i := 0; i+frame <= got; i += frame {
			var sum int32
			for c := 0; c < int(fm.Channels); c++ {
				j := i + c*bps
				if bps == 2 {
					sum += int32(int16(uint16(readBuf[j]) | uint16(readBuf[j+1])<<8))
				} else { // 8 bit unsigned
					sum += (int32(readBuf[j]) - 128) << 8
				}
			}
			pcm[k] = int16(sum / int32(fm.Channels) * volume / 256)
			k++
		}
		cores3.QueuePCMResampled(pcm[:k], fm.SampleRate)
		if pct := read * 100 / int(fm.DataSize); pct >= nextReport {
			s = append(line[:0], "Progress "...)
			s = gfx.Itoa(s, pct)
			log(gfx.String(append(s, "%"...)))
			nextReport += 20
		}
	}
	cores3.FlushResampled() // wait for the end
	cores3.StopSpeaker()
	ms := time.Since(start).Milliseconds()
	s = append(line[:0], "Playback completed! "...)
	s = gfx.Itoa(s, int(ms))
	log(gfx.String(append(s, " ms"...)))
	println("expected", int64(fm.DataSize)*1000/int64(fm.SampleRate)/int64(fm.Channels)/int64(fm.BitsPerSample/8), "ms, TX overruns n/a")
}

func halt() {
	for {
		time.Sleep(time.Second)
	}
}
